"""Quake III CD keys and the q3key files the engine reads them from."""

from __future__ import annotations

from pathlib import Path

KEY_LENGTH = 16
ALPHABET = frozenset("237abcdghjlprstw")
"""Characters the engine accepts in a CD key (Com_CDKeyValidate), in lowercase."""

CHECKSUM_LENGTH = 2
HEX_DIGITS = frozenset("0123456789abcdef")

FILE_FOOTER = (
    "\n// generated by ArenaHub, do not modify\n"
    "// Do not give this file to ANYONE.\n"
    "// id Software will NEVER ask you to send this file to them.\n"
)


def normalize(key: str) -> str:
    """The 16 lowercase characters the engine wants, from a key as Steam shows it.

    Steam gives Quake III keys as ABCD-EFGH-IJKL-MNOP and Team Arena keys with
    the box's 2-digit hex checksum appended (ABCD-EFGH-IJKL-MNOP-XX). The engine
    only reads the first 16 characters of q3key, so the checksum is dropped.
    """
    key = "".join(ch for ch in key.lower() if ch.isalnum())
    if len(key) == KEY_LENGTH + CHECKSUM_LENGTH and set(key[KEY_LENGTH:]) <= HEX_DIGITS:
        key = key[:KEY_LENGTH]
    return key


def is_valid(key: str) -> bool:
    key = normalize(key)
    return len(key) == KEY_LENGTH and set(key) <= ALPHABET


def key_path(install_dir: Path, game_dir: str) -> Path:
    return install_dir / game_dir / "q3key"


def read(install_dir: Path, game_dir: str) -> str | None:
    path = key_path(install_dir, game_dir)
    try:
        key = path.read_text(encoding="ascii", errors="ignore")[:KEY_LENGTH]
    except OSError:
        return None
    return key if is_valid(key) else None


def write(install_dir: Path, game_dir: str, key: str) -> Path:
    """Write the key where the engine looks for it: <game_dir>/q3key."""
    key = normalize(key)
    if not is_valid(key):
        raise ValueError("Not a valid Quake III CD key")
    path = key_path(install_dir, game_dir)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(key + FILE_FOOTER, encoding="ascii", newline="\n")
    return path


def display(key: str) -> str:
    """Format a key the way Steam shows it: ABCD-EFGH-IJKL-MNOP."""
    key = normalize(key).upper()
    return "-".join(key[i : i + 4] for i in range(0, len(key), 4))
